const triggerItems = $items("When Executed by Another Workflow", 0, 0);
if (!triggerItems || !triggerItems.length) {
  throw new Error("Missing input from When Executed by Another Workflow");
}
const trigger = triggerItems[0].json || {};
const ctx = $json || {};

const messages = Array.isArray(ctx.messages) ? ctx.messages : [];
const contextOk =
  messages.length > 0 &&
  messages[0] &&
  typeof messages[0].content === "string" &&
  messages[0].content.trim().length > 0;

let baseSystem = contextOk
  ? messages[0].content
  : "You are the AI assistant for this business. Speak as the business, briefly and naturally. Only state facts you are given; if something is not available, say so briefly and stop. Never invent a business fact.";

const currentMessage =
  typeof trigger.current_message === "string" ? trigger.current_message : "";
const trimmedCurrent = currentMessage.trim();
const hasArabic = /[\u0600-\u06FF]/.test(currentMessage);

// Recent transcript (both roles) -> the human turn, current message last, once.
let convo = messages
  .slice(1)
  .filter(
    (m) =>
      m &&
      (m.role === "user" || m.role === "assistant") &&
      typeof m.content === "string" &&
      m.content.trim()
  )
  .map((m) => ({ role: m.role, content: m.content.trim() }));
if (
  convo.length &&
  convo[convo.length - 1].role === "user" &&
  convo[convo.length - 1].content === trimmedCurrent
) {
  convo = convo.slice(0, -1);
}
const agentInput = convo.length
  ? [
      "Conversation so far - context only (your earlier replies are not authoritative for facts):",
      ...convo.map((m) => (m.role === "assistant" ? "You: " : "Customer: ") + m.content),
      "",
      "Current customer request:",
      currentMessage
    ].join("\n")
  : currentMessage;

// Runtime-only additions to the system prompt (the bulk is built by
// /api/ai-context-vnext -> promptBuilderVNext).
const currentStep = trigger.current_step || null;
const stepHint =
  currentStep === "waiting_for_contact"
    ? "\n\n## Current step\nThe customer was previously asked for their name and phone. If this message contains them, call save_lead."
    : "";
const degraded = contextOk
  ? ""
  : "\n\n## Business context unavailable this turn\nThe business profile and knowledge base could not be loaded. Do not state any specific price, product detail, branch, address or opening time. Use your tools; if a tool cannot answer, tell the customer you will check with the team. Never guess.";
const systemMessage = baseSystem + degraded + stepHint;

// ------------------------------------------------------------------
// Explicit human safety gate - deliberately NARROW and CONSERVATIVE.
// Only an unmistakable, multi-word explicit request for a human.
// No single-word matching, no price / knowledge / greeting detection,
// no business-type vocabulary. Ambiguous cases go to the Agent, which
// also has request_human_handover as a tool.
// ------------------------------------------------------------------
function normGate(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[\u0617-\u061A\u064B-\u0652\u0670\u0640]/g, "")
    .replace(/[\u0625\u0623\u0622]/g, "\u0627")
    .replace(/\u0649/g, "\u064a")
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}
const HUMAN_PHRASES = [
  "\u0628\u062f\u064a \u0627\u062d\u0643\u064a \u0645\u0639 \u0645\u0648\u0638\u0641", "\u0628\u062f\u064a \u0627\u062d\u0643\u064a \u0645\u0639 \u062d\u062f\u0627", "\u0628\u062f\u064a \u0627\u062d\u0643\u064a \u0645\u0639 \u0634\u062e\u0635",
  "\u0628\u062f\u064a \u0627\u062d\u0643\u064a \u0645\u0639 \u0627\u0646\u0633\u0627\u0646", "\u0628\u062f\u064a \u0627\u062a\u0648\u0627\u0635\u0644 \u0645\u0639 \u0645\u0648\u0638\u0641", "\u0628\u062f\u064a \u0627\u062a\u0643\u0644\u0645 \u0645\u0639 \u0645\u0648\u0638\u0641",
  "\u0628\u062f\u064a \u0627\u0643\u0644\u0645 \u0645\u0648\u0638\u0641", "\u0645\u0645\u0643\u0646 \u0627\u062d\u0643\u064a \u0645\u0639 \u0645\u0648\u0638\u0641", "\u0645\u0645\u0643\u0646 \u0627\u062a\u0648\u0627\u0635\u0644 \u0645\u0639 \u0645\u0648\u0638\u0641",
  "\u0628\u062f\u064a \u0645\u0648\u0638\u0641 \u062d\u0642\u064a\u0642\u064a", "\u0628\u062f\u064a \u062d\u062f\u0627 \u062d\u0642\u064a\u0642\u064a", "\u0628\u062f\u064a \u0634\u062e\u0635 \u062d\u0642\u064a\u0642\u064a",
  "\u062d\u0648\u0644\u0646\u064a \u0644\u0645\u0648\u0638\u0641", "\u062d\u0648\u0644\u0646\u064a \u0644\u062d\u062f\u0627", "\u062d\u0648\u0644\u0646\u064a \u0639\u0644\u0649 \u0645\u0648\u0638\u0641", "\u062d\u0648\u0644\u0646\u064a \u0639 \u0645\u0648\u0638\u0641",
  "\u0648\u0635\u0644\u0646\u064a \u0628\u0645\u0648\u0638\u0641", "\u0648\u0635\u0644\u0646\u064a \u0645\u0639 \u0645\u0648\u0638\u0641", "\u0627\u0631\u064a\u062f \u0627\u0644\u062a\u062d\u062f\u062b \u0645\u0639 \u0645\u0648\u0638\u0641", "\u0627\u0631\u064a\u062f \u0627\u0644\u062a\u062d\u062f\u062b \u0627\u0644\u0649 \u0645\u0648\u0638\u0641",
  "talk to a person", "talk to a human", "talk to an agent", "talk to someone",
  "talk to a representative", "talk to a real person", "speak to a person",
  "speak to a human", "speak to an agent", "speak to someone", "speak to a representative",
  "connect me with an agent", "connect me to an agent", "connect me with a person",
  "connect me to a person", "connect me with someone", "connect me to someone",
  "i want a human", "i want to talk to a human", "i want to talk to a person",
  "i want to speak to a person", "i need a human", "get me a human",
  "real person please", "human agent", "live agent"
];
const g = normGate(currentMessage);
const isExplicitHuman = !!g && HUMAN_PHRASES.some((p) => g.indexOf(normGate(p)) !== -1);

// The ONLY two canned strings in VNext: a system-action confirmation
// for the explicit-human gate, and a technical-failure fallback.
const handoffNotice = hasArabic
  ? "\u062a\u0645\u0627\u0645\u060c \u0639\u0645 \u0623\u0648\u0635\u0651\u0644\u0643 \u0644\u062d\u062f\u0627 \u0645\u0646 \u0627\u0644\u0641\u0631\u064a\u0642 \u0648\u0631\u062d \u064a\u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0643 \u0628\u0623\u0642\u0631\u0628 \u0648\u0642\u062a. \ud83d\ude4f"
  : "Sure - I am connecting you with someone from our team; they will follow up with you shortly.";
const fallbackReply = hasArabic
  ? "\u0622\u0633\u0641\u064a\u0646\u060c \u0635\u0627\u0631 \u0639\u0646\u0627 \u062e\u0644\u0644 \u062a\u0642\u0646\u064a \u0628\u0633\u064a\u0637 \u0647\u0644\u0642. \u0645\u0645\u0643\u0646 \u062a\u0628\u0639\u062a \u0631\u0633\u0627\u0644\u062a\u0643 \u0645\u0631\u0629 \u062a\u0627\u0646\u064a\u0629 \u0628\u0639\u062f \u0634\u0648\u064a\u061f"
  : "Sorry - we hit a brief technical issue on our side. Could you send your message again in a little while?";

return [
  {
    json: {
      conversation_id: trigger.conversation_id || null,
      client_id: trigger.client_id || null,
      message_id: trigger.message_id || null,
      channel: trigger.channel || null,
      current_message: currentMessage,
      agent_input: agentInput,
      system_message: systemMessage,
      context_ok: contextOk,
      is_explicit_human: isExplicitHuman,
      handoff_notice: handoffNotice,
      fallback_reply: fallbackReply
    }
  }
];

