parameters.jsCode:
const agent = $json || {};

const prepItems = $items("Prepare Context", 0, 0);
const prep = prepItems && prepItems.length ? (prepItems[0].json || {}) : {};

// Did the explicit-human safety gate fire (the Agent did not run)?
let gateForced = false;
let gateResp = {};
try {
  const fh = $items("Force Human Handover", 0, 0);
  if (fh && fh.length) {
    gateForced = true;
    gateResp = fh[0].json || {};
  }
} catch (e) {}

// Extract the agent reply text (tolerate a JSON blob).
let raw = "";
if (agent.output != null) raw = agent.output;
else if (agent.text != null) raw = agent.text;
else if (agent.response != null) raw = agent.response;
if (raw && typeof raw === "object") {
  try {
    raw = raw.reply || raw.text || raw.message || JSON.stringify(raw);
  } catch (e) {
    raw = "";
  }
}
let replyText = String(raw || "").trim();
if (replyText.startsWith("{") && replyText.endsWith("}")) {
  try {
    const p = JSON.parse(replyText);
    if (p && typeof p === "object") replyText = String(p.reply || p.text || p.message || "").trim();
  } catch (e) {}
}
// Strip a stray #intent: trailer if the model added one (VNext never asks for it).
replyText = replyText.replace(/\s*#intent:\s*[a-z_]+\s*$/i, "").trim();

const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];
const hadSteps = steps.length > 0;

const toolsUsed = [];
let obsStatus = null;
let obsStep = null;
let obsQuick = null;
let handoverToolOk = false;
for (const step of steps) {
  const tool = (step && step.action && step.action.tool) || (step && step.tool) || null;
  if (tool) toolsUsed.push(tool);
  let obs = step && step.observation;
  if (typeof obs === "string") {
    try {
      obs = JSON.parse(obs);
    } catch (e) {
      obs = null;
    }
  }
  if (obs && typeof obs === "object") {
    if (obs.conversation_status) obsStatus = obs.conversation_status;
    if (obs.current_step) obsStep = obs.current_step;
    if (obs.quick_reply_action) obsQuick = obs.quick_reply_action;
    if (
      tool === "request_human_handover" &&
      (obs.ok === true ||
        obs.action === "human_handover" ||
        obs.conversation_status === "waiting_human")
    ) {
      handoverToolOk = true;
    }
  }
}

// --- explicit-human-gate path -----------------------------------
if (gateForced) {
  const forcedOk =
    gateResp.error === undefined &&
    (gateResp.ok === true ||
      gateResp.action === "human_handover" ||
      gateResp.conversation_status === "waiting_human");
  return [
    {
      json: {
        reply: prep.handoff_notice || "A teammate will follow up with you shortly.",
        intent: "human_request",
        action: "human_handover",
        quick_reply_action: null,
        conversation_status: "waiting_human",
        current_step: null,
        handover_done: forcedOk,
        handover_unconfirmed: !forcedOk
      }
    }
  ];
}

// --- genuine technical failure ---------------------------------
if (replyText === "" && !hadSteps) {
  return [
    {
      json: {
        reply: prep.fallback_reply || "Sorry - we hit a brief technical issue. Please send your message again shortly.",
        intent: "unknown",
        action: null,
        quick_reply_action: null,
        conversation_status: null,
        current_step: null,
        handover_done: false,
        handover_unconfirmed: false
      }
    }
  ];
}

// --- normal agent path: derive from EXECUTED TOOLS -------------
let action = null;
let intent = "unknown";
if (toolsUsed.includes("request_human_handover")) {
  action = "human_handover";
  intent = "human_request";
} else if (toolsUsed.includes("request_conversation_close")) {
  action = "close_needs_confirmation";
  intent = "closing";
} else if (toolsUsed.includes("save_lead")) {
  action = "lead_saved";
  intent = "lead";
} else if (toolsUsed.includes("start_order") || toolsUsed.includes("continue_order")) {
  action = "order_in_progress";
  intent = "order";
}

// The close tool writes conversations.current_step = "closing_confirm"
// server-side. Surface the step + quick reply from the EXECUTED TOOL
// (reliable) rather than only the fragile observation string, so the
// parent persists it and renders the confirm buttons this turn.
if (action === "close_needs_confirmation") {
  if (!obsStep) obsStep = "closing_confirm";
  if (!obsQuick) obsQuick = "closing_confirm";
}

let conversationStatus = obsStatus || null;
if (!conversationStatus && intent === "human_request") conversationStatus = "waiting_human";

return [
  {
    json: {
      reply: replyText || prep.fallback_reply || "",
      intent,
      action,
      quick_reply_action: obsQuick || null,
      conversation_status: conversationStatus,
      current_step: obsStep || null,
      handover_done: intent === "human_request" ? handoverToolOk : false,
      handover_unconfirmed: intent === "human_request" && !handoverToolOk
    }
  }
];
